/* Georgian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Giorgi": "farmer, earthworker — Greek Georgios", "Nino": "The enlightener of Georgia; the iconic feminine name.", "Davit": "beloved — Hebrew David", "Tamar": "palm tree — Hebrew", "Irakli": "glory of Hera — Greek Herakles", "Mariam": "A beloved feminine name.", "Shevardnadze": "Family name of Eduard Shevardnadze.", "Saakashvili": "Family name of Mikheil Saakashvili.", "Margvelashvili": "Family name of Giorgi Margvelashvili.", "Ivanishvili": "Family name of Bidzina Ivanishvili."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Giorgi';
console.log(lookup(q));

